<?php
require_once __DIR__.'/workflow-fixture.php';
function schema_test_packet(string $rid,array $task,string $outcome='completed',bool $current=true): array {
 $d=wf_test_payload($rid,$task,$outcome);$snapshot=wf_snapshot($rid);$package=json_decode($snapshot['package_json'],true);if($current)$package['workflow']['packet_contract_version']=WF_PACKET_VERSION;else unset($package['workflow']['packet_contract_version']);$json=json_encode($package,JSON_PRETTY_PRINT|JSON_UNESCAPED_SLASHES|JSON_HEX_TAG|JSON_THROW_ON_ERROR);$hash=hash('sha256',$json);$s=one('SELECT * FROM workflow_snapshots WHERE research_id=? AND sha256=? AND public_allowed=1',[$rid,$hash]);
 if(!$s){$s=['id'=>uid(),'research_id'=>$rid,'round_no'=>$snapshot['round_no'],'context_version'=>$snapshot['context_version'],'package_json'=>$json,'sha256'=>$hash,'created_at'=>now()];insert('workflow_snapshots',$s);}
 $d['context_id']=$s['id'];$d['handoff_code']=wf_handoff_code($task,$s,$d['submission_key']);
 if($current){$d['usefulness']=['version'=>1,'question_helped'=>'Which parts of this explicitly synthetic research workflow are checkable?','intended_user'=>'A local software reviewer testing the workflow; this fixture is not scientific research.','finding'=>'This synthetic packet organizes a checkable uncertainty record. It establishes no scientific conclusion.','why_it_matters'=>'A later reviewer can inspect the retained fixture and see exactly what was and was not checked.','increment'=>'The supplied evidence, access limits and next-use instructions are organized into a reusable audit trail.','established'=>'Only deterministic local workflow behavior is exercised; no scientific endpoint or impact is established.','uncertain'=>'Real-world scientific effects, applicability and independent source support remain unexamined.','reusable_output'=>'The retained synthetic result, source registry and method are available for a later local regression check.','next_use'=>'A separate reviewer can reproduce the local checks and investigate real sources before any scientific conclusion.'];
 $d['body'].="\n\n".$d['usefulness']['finding'];
 $d['evidence']['usefulness_reviews']=[];foreach(wf_usefulness_review_template($task) as $review){$target=one('SELECT body FROM workflow_submissions WHERE id=?',[$review['result_id']]);$review['verdict']='useful';$review['reason']='The retained synthetic output organizes checkable workflow evidence against this local fixture deliverable; no real scientific usefulness is established.';$review['output_quote']=$target['body'];$review['next_use']='Use this retained synthetic record to reproduce a local software regression check only.';$d['evidence']['usefulness_reviews'][]=$review;}}
 else unset($d['usefulness'],$d['evidence']['usefulness_reviews']);return $d;
}
function schema_test_create(string $suffix=''): array {
 $_SESSION['admin']=1;$r=create_research(['title'=>'[QA] Readable synthetic results '.$suffix.' '.uid(),'question'=>'Check readable synthetic uncertainty and packet repair without asserting a scientific finding.','category_id'=>one('SELECT id FROM categories LIMIT 1')['id'],'terms'=>1]);moderate('request',$r['id'],'Approved','Approve an explicitly synthetic local readability fixture.');return research($r['id']);
}
